/* Full-page photo shader background: dissolve-in, cursor ripples, scroll parallax, light/dark aware. */
(() => {
  const cv = document.getElementById("photo-shader");
  if (!cv) return;
  const pct = document.querySelector(".ph-pct");
  const root = document.documentElement;
  const IMG = "data:image/jpeg;base64,";
  const calm = matchMedia("(prefers-reduced-motion: reduce)").matches ? 0.25 : 1;
  const fallback = () => {
    cv.style.display = "none";
    cv.parentElement.style.background = `linear-gradient(rgba(var(--shade),.7),rgba(var(--shade),.7)),url(${IMG}) 72% 55%/cover`;
    if (pct) pct.remove();
  };
  const gl = cv.getContext("webgl", { antialias: false, alpha: true, premultipliedAlpha: false });
  if (!gl) return fallback();

  const VS = "attribute vec2 p;varying vec2 vUv;void main(){vUv=p*.5+.5;gl_Position=vec4(p,0.,1.);}";
  const FS = `precision highp float;
uniform sampler2D uTex;uniform vec2 uRes,uImg,uMouse,uFocus;uniform float uTime,uVel,uReveal,uCalm,uTheme;varying vec2 vUv;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
vec2 cover(vec2 uv,float zoom){
  float r=uRes.x/uRes.y,ir=uImg.x/uImg.y;
  vec2 s=(r>ir?vec2(1.,ir/r):vec2(r/ir,1.))*zoom;
  vec2 c=clamp(uFocus,s*.5,1.-s*.5);
  return (uv-.5)*s+c;
}
void main(){
  vec2 uv=vUv,asp=vec2(uRes.x/uRes.y,1.);
  float t=uTime*.12;
  vec2 flow=(vec2(n(uv*4.+t),n(uv*4.-t+7.))-.5)*.012*uCalm;
  vec2 d=(uv-uMouse)*asp;float dist=length(d);
  float fall=exp(-dist*dist*9.);
  float wave=sin(dist*34.-uTime*5.)*fall;
  vec2 dir=d/(dist+1e-4);
  vec2 disp=dir*wave*(.008+uVel*.05)*uCalm+flow;
  float nz=n(uv*4.)*.6+n(uv*11.)*.4;
  float edge=uReveal*1.5-.25;
  float rv=1.-smoothstep(edge-.14,edge,nz);
  vec2 base=cover(uv,.88+.12*uReveal)+disp;
  float ca=(.003+uVel*.02+(1.-uReveal)*.02)*(.4+fall*3.);
  vec3 c=vec3(texture2D(uTex,base+dir*ca).r,texture2D(uTex,base).g,texture2D(uTex,base-dir*ca).b);
  c+=wave*.05*uCalm;
  c*=1.-.6*pow(length((uv-.5)*vec2(.9,1.)),2.4);
  vec3 dark=c*.4;
  vec3 light=mix(c,vec3(.96,.96,.97),.74);
  c=mix(dark,light,uTheme);
  c+=(h(gl_FragCoord.xy+fract(uTime)*91.)-.5)*.05;
  gl_FragColor=vec4(c,rv);
}`;
  const sh = (t, s) => { const o = gl.createShader(t); gl.shaderSource(o, s); gl.compileShader(o); return o; };
  const pr = gl.createProgram();
  gl.attachShader(pr, sh(gl.VERTEX_SHADER, VS));
  gl.attachShader(pr, sh(gl.FRAGMENT_SHADER, FS));
  gl.linkProgram(pr);
  if (!gl.getProgramParameter(pr, gl.LINK_STATUS)) {
    console.error("photo shader link error:", gl.getProgramInfoLog(pr));
    return fallback();
  }
  gl.useProgram(pr);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(pr, "p");
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
  const U = (n) => gl.getUniformLocation(pr, n);
  const u = { res: U("uRes"), img: U("uImg"), m: U("uMouse"), f: U("uFocus"), t: U("uTime"), v: U("uVel"), r: U("uReveal"), c: U("uCalm"), th: U("uTheme") };

  let iw = 1, ih = 1, ready = false, started = 0;
  const m = { x: 0.5, y: 0.5 }, tg = { x: 0.5, y: 0.5 };
  let vel = 0, touched = false, fy = 0.62;
  const themeNow = () => (root.dataset.theme === "light" ? 1 : 0);
  let theme = themeNow();

  const size = () => {
    const d = Math.min(devicePixelRatio || 1, 2);
    const w = Math.round(cv.clientWidth * d), h = Math.round(cv.clientHeight * d);
    if (w && h && (cv.width !== w || cv.height !== h)) { cv.width = w; cv.height = h; gl.viewport(0, 0, w, h); }
  };
  addEventListener("resize", size);

  const move = (e) => { touched = true; tg.x = e.clientX / innerWidth; tg.y = 1 - e.clientY / innerHeight; };
  addEventListener("pointermove", move, { passive: true });
  addEventListener("pointerdown", (e) => { move(e); vel = Math.min(vel + 0.6, 1); }, { passive: true });
  root.addEventListener("pointerleave", () => { touched = false; });

  const im = new Image();
  im.onload = () => {
    const tex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, im);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    iw = im.width; ih = im.height; ready = true; started = performance.now();
  };
  im.src = IMG;

  const loop = (now) => {
    size();
    if (ready) {
      const s = (now - started) / 1000;
      const p = calm < 1 ? 1 : Math.min(s / 2.2, 1);
      const reveal = 1 - Math.pow(1 - p, 3);
      if (pct) { pct.textContent = Math.round(p * 100) + "%"; if (p >= 1) pct.classList.add("done"); }
      if (!touched) { const a = now / 1000; tg.x = 0.5 + 0.3 * Math.sin(a * 0.45); tg.y = 0.45 + 0.2 * Math.sin(a * 0.31 + 1); }
      const dx = tg.x - m.x, dy = tg.y - m.y;
      m.x += dx * 0.08; m.y += dy * 0.08;
      vel += (Math.min(Math.hypot(dx, dy) * 14, 1) - vel) * 0.12;
      vel *= 0.985;
      const prog = Math.min(scrollY / Math.max(root.scrollHeight - innerHeight, 1), 1);
      fy += (0.62 - 0.24 * prog - fy) * 0.08;
      theme += (themeNow() - theme) * 0.08;
      gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
      gl.uniform2f(u.res, cv.width, cv.height); gl.uniform2f(u.img, iw, ih);
      gl.uniform2f(u.m, m.x, m.y); gl.uniform2f(u.f, 0.72, fy);
      gl.uniform1f(u.t, now / 1000); gl.uniform1f(u.v, vel);
      gl.uniform1f(u.r, reveal); gl.uniform1f(u.c, calm); gl.uniform1f(u.th, theme);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    }
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
